package com.trampolim.api.observatory;
import java.util.*;import java.time.*;import com.trampolim.api.geography.TerritorialCatalog;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service @ConditionalOnProperty(name="trampolim.datasource.capacita.enabled",havingValue="true")
public class LearningObservatory extends SnapshotBatch {
 private final TerritorialCatalog geo;@Value("${career.observatory-capture-enabled:true}")private boolean enabled;
 public LearningObservatory(@Qualifier("capacitaJdbcTemplate")JdbcTemplate db,@Qualifier("capacitaTransactionManager")PlatformTransactionManager manager,TerritorialCatalog geo){super(db,manager);this.geo=geo;}
 @Scheduled(initialDelayString="${observatory.v2.refresh-ms:900000}",fixedDelayString="${observatory.v2.refresh-ms:900000}")public void scheduled(){if(enabled)enqueue();}
 protected void build(UUID id,LocalDate from,Instant observed){
 String cohort="WITH cohort AS (SELECT k.student_id,k.region_code,k.consent_at FROM learning_observatory_consents k JOIN student_users u ON u.id=k.student_id WHERE u.email_verified=TRUE AND u.account_status='ACTIVE'), eligible AS (SELECT h.student_id,h.region_code,h.consent_at,c.id AS course_id FROM cohort h JOIN learning_lesson_progress p ON p.student_id=h.student_id JOIN learning_lessons l ON l.id=p.lesson_id JOIN learning_modules m ON m.id=l.module_id JOIN learning_subjects s ON s.id=m.subject_id JOIN learning_courses c ON c.id=s.course_id JOIN student_users t ON t.id=c.teacher_id WHERE c.status='PUBLISHED' AND c.moderation_blocked=FALSE AND t.account_status='ACTIVE' GROUP BY h.student_id,h.region_code,h.consent_at,c.id), lessons AS (SELECT h.student_id,h.region_code,h.consent_at,h.course_id,count(l.id) AS total,count(p.completed_at) AS completed,max(p.completed_at) AS last_lesson FROM eligible h JOIN learning_subjects s ON s.course_id=h.course_id JOIN learning_modules m ON m.subject_id=s.id JOIN learning_lessons l ON l.module_id=m.id AND l.status='PUBLISHED' AND l.validation_status='READY' LEFT JOIN learning_lesson_progress p ON p.lesson_id=l.id AND p.student_id=h.student_id GROUP BY h.student_id,h.region_code,h.consent_at,h.course_id), required AS (SELECT l.student_id,l.course_id,a.id,min(t.submitted_at) AS first_pass FROM lessons l JOIN learning_assessments a ON a.course_id=l.course_id AND a.status='PUBLISHED' JOIN learning_assessment_versions v ON v.id=a.current_version_id AND (v.definition->>'requiredForCompletion')::boolean=TRUE LEFT JOIN learning_assessment_attempts t ON t.assessment_id=a.id AND t.student_id=l.student_id AND t.status='SUBMITTED' AND t.passed=TRUE GROUP BY l.student_id,l.course_id,a.id), done AS (SELECT l.*,greatest(l.last_lesson,(SELECT max(r.first_pass) FROM required r WHERE r.student_id=l.student_id AND r.course_id=l.course_id)) AS completed_at FROM lessons l WHERE total>0 AND total=completed AND NOT EXISTS(SELECT 1 FROM required r WHERE r.student_id=l.student_id AND r.course_id=l.course_id AND r.first_pass IS NULL)) ";
 db.update(cohort+"INSERT INTO observatory_personal_cells(run_id,metric,month,state,value,contributors) SELECT ?,'COURSE_COMPLETIONS',date_trunc('month',completed_at AT TIME ZONE 'America/Sao_Paulo')::date,region_code,count(*),count(DISTINCT student_id) FROM done WHERE completed_at>=consent_at AND completed_at>=(?::date::timestamp AT TIME ZONE 'America/Sao_Paulo') AND completed_at<=? GROUP BY 3,4",id,from,java.sql.Timestamp.from(observed));
 db.update("INSERT INTO observatory_personal_cells(run_id,metric,month,state,value,contributors) SELECT ?,'VERIFIED_AWARDS',date_trunc('month',a.awarded_at AT TIME ZONE 'America/Sao_Paulo')::date,c.region_code,count(*),count(DISTINCT a.student_id) FROM learning_competency_awards a JOIN learning_assessment_attempts t ON t.id=a.attempt_id AND t.student_id=a.student_id AND t.assessment_id=a.assessment_id AND t.score_percent=a.score_percent AND t.status='SUBMITTED' AND t.passed=TRUE JOIN learning_observatory_consents c ON c.student_id=a.student_id JOIN student_users u ON u.id=a.student_id WHERE u.account_status='ACTIVE' AND u.email_verified=TRUE AND a.revoked_at IS NULL AND (a.valid_until IS NULL OR a.valid_until>?) AND a.awarded_at>=c.consent_at AND a.awarded_at>=(?::date::timestamp AT TIME ZONE 'America/Sao_Paulo') AND a.awarded_at<=? GROUP BY 3,4",id,java.sql.Timestamp.from(observed),from,java.sql.Timestamp.from(observed));
 }
 public Map<String,Object> indicators(String from,String to,String state){period(from,to);if(!geo.states().contains(state))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Selecione uma UF válida.");return read(()->{var run=current();if(!run.get("status").equals("READY"))return Map.of("status",run.get("status"),"items",List.of());if((month(from).atDay(1).isBefore(((java.sql.Date)run.get("coverage_from")).toLocalDate())||month(to).isAfter(YearMonth.from(((java.sql.Date)run.get("coverage_through")).toLocalDate()))))return Map.of("status","OUTSIDE_COVERAGE","items",List.of());var rows=db.queryForList("SELECT metric,month,value,contributors FROM observatory_personal_cells WHERE run_id=? AND state=? AND month>=? AND month<=?",run.get("id"),state,month(from).atDay(1),month(to).atDay(1));var index=new HashMap<String,Map<String,Object>>();for(var r:rows)index.put(r.get("metric")+":"+r.get("month"),r);var items=new ArrayList<Map<String,Object>>();for(YearMonth m=month(from);!m.isAfter(month(to));m=m.plusMonths(1)){var item=new LinkedHashMap<String,Object>();item.put("month",m.toString());for(String metric:List.of("COURSE_COMPLETIONS","VERIFIED_AWARDS")){var r=index.get(metric+":"+m.atDay(1));item.put(metric,r==null?privateBand(0,0,0,false):privateBand(count(r,"value"),count(r,"contributors"),0,false));}items.add(item);}return Map.of("status","READY","observedAt",run.get("observed_at"),"state",state,"geographicBasis","UF declarada no consentimento regional, não endereço residencial nem município do curso.","items",items);});}
}
